<script lang="ts">
 import {languageOverrides} from "./localization";
 import {RefreshCw,Save,ChartNoAxesCombined,BookOpen,PinOff,Settings2,Wallet,ReceiptText,TriangleAlert,CalendarDays,Grip} from '@lucide/svelte';import {translator} from './i18n';import {uiLabel} from './english';
 export let language:'ru'|'ro'|'en';export let databaseId:string;export let period:string;export let charges:string;export let paid:string;export let balance:string;export let attention:number;export let onopen:(id:string)=>void;
 let area:HTMLDivElement,button:HTMLButtonElement,pinned:string[]=[],positions:Record<string,{x:number;y:number}>={},configure=false,loadedId='',popover={x:0,y:0},drag:{id:string;dx:number;dy:number}|null=null;$:t=translator(language,$languageOverrides);
 const widgets=[{id:'balance',ru:'Остаток к оплате',ro:'Sold de achitat',en:'Balance due',icon:Wallet,action:'reports'},{id:'charges',ru:'Начисления',ro:'Calcule',en:'Charges',icon:ReceiptText,action:'receipts'},{id:'paid',ru:'Поступило оплат',ro:'Plăți încasate',en:'Payments received',icon:Wallet,action:'payment-report'},{id:'attention',ru:'Требует внимания',ro:'Necesită atenție',en:'Needs attention',icon:TriangleAlert,action:'readings'},{id:'period',ru:'Расчётный период',ro:'Perioada de calcul',en:'Billing period',icon:CalendarDays,action:'period'}];
 function read(){try{const saved=JSON.parse(localStorage.getItem('openhau-widgets-'+databaseId)||'[]');pinned=(Array.isArray(saved)?saved:saved.pinned||[]).filter((id:string)=>widgets.some(w=>w.id===id));positions=Array.isArray(saved)?{}:saved.positions||{};}catch{pinned=[];positions={};}loadedId=databaseId;}
 $:if(databaseId!==loadedId)read();
 function store(){localStorage.setItem('openhau-widgets-'+databaseId,JSON.stringify({pinned,positions}));}
 function toggle(id:string){if(pinned.includes(id))pinned=pinned.filter(value=>value!==id);else{positions={...positions,[id]:positions[id]||{x:Math.max(12,(area?.clientWidth||800)-410),y:20+pinned.length*140}};pinned=[...pinned,id];}store();}
 function position(id:string,index:number){const r=positions[id]||{x:Math.max(12,(area?.clientWidth||800)-410),y:20+index*140};return {x:Math.max(0,Math.min((area?.clientWidth||1200)-240,r.x)),y:Math.max(0,Math.min((area?.clientHeight||800)-130,r.y))};}
 function move(e:PointerEvent){if(!drag||!area)return;const rect=area.getBoundingClientRect();positions={...positions,[drag.id]:{x:Math.max(0,Math.min(rect.width-240,e.clientX-rect.left-drag.dx)),y:Math.max(0,Math.min(rect.height-130,e.clientY-rect.top-drag.dy))}};}
 function end(){if(drag){drag=null;store();}}
 function showOptions(){configure=!configure;if(configure){const r=button.getBoundingClientRect();popover={x:Math.max(8,Math.min(window.innerWidth-268,r.left+r.width/2-130)),y:Math.max(8,r.top-245)};}}
</script>
<svelte:window onpointermove={move} onpointerup={end}/>
<div class="widget-layer" bind:this={area}>
 <aside class="desktop-widgets"><button class="desktop-shortcut" onclick={()=>onopen('file:save')}><Save size={29}/><span>{t('Сохранить','Salvează')}</span></button><button class="desktop-shortcut" onclick={()=>onopen('overview')}><ChartNoAxesCombined size={29}/><span>{t('Обзор','Prezentare')}</span></button><button class="desktop-shortcut" onclick={()=>onopen('manual')}><BookOpen size={29}/><span>{t('Документация','Documentație')}</span></button><button class="desktop-shortcut" onclick={()=>onopen('updates')}><RefreshCw size={29}/><span>{t('Обновления','Actualizări')}</span></button></aside>
 {#each pinned as id,index}{@const widget=widgets.find(w=>w.id===id)!}{@const at=position(id,index)}<section class="desktop-widget" style:left={at.x+'px'} style:top={at.y+'px'}><header role="toolbar" aria-label="Move widget" tabindex="0" onkeydown={e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();positions={...positions,[id]:{x:Math.max(0,at.x+(e.key==='ArrowRight'?10:e.key==='ArrowLeft'?-10:0)),y:Math.max(0,at.y+(e.key==='ArrowDown'?10:e.key==='ArrowUp'?-10:0))}};store();}} onpointerdown={e=>{if((e.target as Element).closest('button')||e.button!==0)return;const r=e.currentTarget.parentElement!.getBoundingClientRect();drag={id,dx:e.clientX-r.left,dy:e.clientY-r.top};e.currentTarget.setPointerCapture(e.pointerId);}}><widget.icon size={17}/><span>{uiLabel(widget,language,$languageOverrides)}</span><Grip size={14}/><button aria-label={t('Открепить виджет','Elimină widgetul')} onclick={()=>toggle(id)}><PinOff size={14}/></button></header><button class="widget-value" onclick={()=>onopen(widget.action)}>{id==='balance'?balance:id==='charges'?charges:id==='paid'?paid:id==='attention'?attention:period}{#if ['balance','charges','paid'].includes(id)}<small>MDL</small>{/if}</button></section>{/each}
 <button bind:this={button} class="widget-configure" aria-expanded={configure} onclick={showOptions}><Settings2 size={16}/>{t('Виджеты','Widgeturi')}</button>
 {#if configure}<section class="widget-options" style:left={popover.x+'px'} style:top={popover.y+'px'}>{#each widgets as widget}<label class="check-row"><input type="checkbox" checked={pinned.includes(widget.id)} onchange={()=>toggle(widget.id)}/>{uiLabel(widget,language,$languageOverrides)}</label>{/each}</section>{/if}
</div>
<style>.widget-layer{position:absolute;inset:0;pointer-events:none;z-index:0}.desktop-widgets{position:absolute;right:12px;top:16px;width:130px;display:grid;gap:12px;pointer-events:auto}.desktop-shortcut{width:130px;display:flex;flex-direction:column;align-items:center;gap:9px;padding:10px;background:none;color:var(--text);border:0;font-size:12px}.desktop-shortcut :global(svg){color:var(--accent)}.widget-configure{position:absolute;right:12px;bottom:12px;width:130px;display:flex;justify-content:center;gap:7px;align-items:center;background:none;border:0;color:var(--muted);padding:8px;pointer-events:auto}.widget-options,.desktop-widget{box-sizing:border-box;padding:14px;background:color-mix(in srgb,var(--surface) 88%,transparent);backdrop-filter:blur(20px);border:1px solid var(--border);box-shadow:0 4px 18px #0002;pointer-events:auto}.desktop-widget{position:absolute;width:240px;min-height:120px}.desktop-widget header{display:flex;gap:8px;align-items:center;font-size:12px;cursor:move;touch-action:none;user-select:none}.desktop-widget header span{flex:1}.desktop-widget header button{border:0;background:none;color:var(--muted);padding:5px}.widget-value{display:flex;gap:7px;align-items:baseline;background:none;border:0;color:var(--text);padding:18px 0 0;font-size:24px;font-weight:600;max-width:100%;overflow-wrap:anywhere}.widget-value small{font-size:11px;font-weight:400;color:var(--muted)}.widget-options{position:fixed;width:260px;display:grid;gap:14px;z-index:15000}</style>
